import{_ as t,o as d,c as a,a3 as o}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"XiHan.Framework.SearchEngines.Abstractions","description":"","frontmatter":{},"headers":[],"relativePath":"packages/search-engines-abstractions.md","filePath":"packages/search-engines-abstractions.md","lastUpdated":1786268168000}'),c={name:"packages/search-engines-abstractions.md"};function r(n,e,s,i,h,l){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="xihan-framework-searchengines-abstractions" tabindex="-1">XiHan.Framework.SearchEngines.Abstractions <a class="header-anchor" href="#xihan-framework-searchengines-abstractions" aria-label="Permalink to &quot;XiHan.Framework.SearchEngines.Abstractions&quot;">​</a></h1><blockquote><p>搜索引擎抽象包：索引、文档、检索请求与结果的统一契约。<strong>不含任何搜索引擎实现，零第三方依赖。</strong></p></blockquote><ul><li><strong>NuGet</strong>：<code>XiHan.Framework.SearchEngines.Abstractions</code></li><li><strong>模块类</strong>：无（纯契约包，直接引用即可）</li><li><strong>所在层</strong>：应用层（抽象）</li><li><strong>关键依赖</strong>：无</li></ul><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><code>ISearchEngine</code> 是框架的搜索契约。它按「<strong>Elasticsearch 与 PostgreSQL 全文检索都能落地</strong>」的交集设计——签名中<strong>不出现任一后端的类型</strong>，因此换实现不需要改调用方。</p><p>投递语义：索引与删除均为<strong>幂等的按标识覆盖/移除</strong>；写入对检索可见的延迟由实现决定，需要立即可见时调 <code>RefreshAsync</code>。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>业务代码只想依赖检索能力，不想把 Elasticsearch 客户端类型渗进去。</li><li>想自己接一个后端（PostgreSQL 全文检索、Meilisearch、OpenSearch…）：实现 <code>ISearchEngine</code> 一个接口即可。</li><li>测试里想用进程内实现替换真实引擎。</li></ul><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> XiHan.Framework.SearchEngines.Abstractions</span></span></code></pre></div><p>契约包没有模块类，引用后直接用类型即可。要拿到可注入的 <code>ISearchEngine</code>，引 <a href="./search-engines">XiHan.Framework.SearchEngines</a>（进程内实现）或 <a href="./search-engines-elasticsearch">XiHan.Framework.SearchEngines.Elasticsearch</a>。</p><h2 id="主要-api-类型" tabindex="-1">主要 API / 类型 <a class="header-anchor" href="#主要-api-类型" aria-label="Permalink to &quot;主要 API / 类型&quot;">​</a></h2><h3 id="isearchengine" tabindex="-1"><code>ISearchEngine</code> <a class="header-anchor" href="#isearchengine" aria-label="Permalink to &quot;`ISearchEngine`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>IndexExistsAsync(index)</code></td><td>索引是否存在</td></tr><tr><td><code>CreateIndexAsync(definition)</code></td><td>创建索引，已存在时不做任何事；返回<strong>本次是否实际创建</strong></td></tr><tr><td><code>DeleteIndexAsync(index)</code></td><td>删除索引，不存在时不做任何事；返回<strong>本次是否实际删除</strong></td></tr><tr><td><code>IndexAsync&lt;TDocument&gt;(index, document)</code></td><td>写入单个文档，标识已存在时<strong>整体覆盖</strong></td></tr><tr><td><code>IndexManyAsync&lt;TDocument&gt;(index, documents)</code></td><td>批量写入，返回实际写入数</td></tr><tr><td><code>DeleteAsync(index, id)</code></td><td>按标识删除文档</td></tr><tr><td><code>GetAsync&lt;TDocument&gt;(index, id)</code></td><td>按标识取文档，不存在返回 <code>null</code></td></tr><tr><td><code>SearchAsync&lt;TDocument&gt;(request)</code></td><td>检索，返回 <code>SearchResult&lt;TDocument&gt;</code></td></tr><tr><td><code>RefreshAsync(index)</code></td><td>使此前的写入<strong>立即对检索可见</strong></td></tr></tbody></table><h3 id="索引定义" tabindex="-1">索引定义 <a class="header-anchor" href="#索引定义" aria-label="Permalink to &quot;索引定义&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>SearchIndexDefinition</code></td><td>索引定义：<code>Name</code>、<code>Fields</code>、<code>Language</code>（分词语言，可选）</td></tr><tr><td><code>SearchFieldDefinition</code></td><td>字段定义（record）：<code>Name</code>、<code>Type</code>、<code>Searchable</code>（默认 <code>false</code>）、<code>Sortable</code>（默认 <code>false</code>）</td></tr><tr><td><code>SearchFieldType</code></td><td><code>Text</code>（分词全文）/ <code>Keyword</code>（不分词精确）/ <code>Integer</code> / <code>Double</code> / <code>Boolean</code></td></tr></tbody></table><h3 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to &quot;文档&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>SearchDocument&lt;TDocument&gt;</code></td><td>「标识 + 文档体」的载体，索引与批量索引都用它</td></tr></tbody></table><h3 id="检索请求" tabindex="-1">检索请求 <a class="header-anchor" href="#检索请求" aria-label="Permalink to &quot;检索请求&quot;">​</a></h3><p><code>SearchRequest</code>（构造时传索引名，其余用 <code>init</code> 属性）：</p><table tabindex="0"><thead><tr><th>属性</th><th>说明</th></tr></thead><tbody><tr><td><code>Index</code></td><td>索引名</td></tr><tr><td><code>Keyword</code></td><td>关键字，为空时<strong>只按过滤条件检索</strong></td></tr><tr><td><code>Fields</code></td><td>关键字检索的字段范围</td></tr><tr><td><code>Filters</code></td><td><code>SearchFilter[]</code> 过滤条件</td></tr><tr><td><code>Sorts</code></td><td><code>SearchSort[]</code> 排序</td></tr><tr><td><code>HighlightFields</code></td><td>需要高亮的字段</td></tr><tr><td><code>Skip</code> / <code>Take</code></td><td>分页</td></tr></tbody></table><p><code>SearchFilter(field, op, value, values)</code>，<code>SearchFilterOperator</code> 取值：<code>Equal</code> / <code>NotEqual</code> / <code>In</code> / <code>GreaterThan</code> / <code>GreaterThanOrEqual</code> / <code>LessThan</code> / <code>LessThanOrEqual</code> / <code>Exists</code>。</p><blockquote><p><code>In</code> 必须用 <code>values</code> 传集合，且不能为空——构造函数会直接校验并抛异常。</p></blockquote><p><code>SearchSort(field, direction)</code>，方向为 <code>SearchSortDirection.Ascending</code> / <code>Descending</code>；字段取 <code>SearchSort.ScoreField</code>（<code>&quot;_score&quot;</code>）表示按相关度排序，<code>SearchSort.ByScore</code> 是「相关度降序」的现成实例。</p><h3 id="结果" tabindex="-1">结果 <a class="header-anchor" href="#结果" aria-label="Permalink to &quot;结果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>SearchResult&lt;TDocument&gt;</code></td><td><code>Hits</code>（命中列表）+ <code>TotalCount</code>（总数），另有现成的 <code>Empty</code></td></tr><tr><td><code>SearchHit&lt;TDocument&gt;</code></td><td>单条命中（record）：<code>Id</code>、<code>Document</code>、<code>Score</code>（<strong>未按相关度检索时为 0</strong>）、<code>Highlights</code>（键为字段名）</td></tr></tbody></table><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>契约是<strong>交集设计</strong>：能力更强的后端（如 Elasticsearch 的聚合、复杂 DSL）不在这层暴露，需要时直接用该后端的客户端。</li><li><code>CreateIndexAsync</code> / <code>DeleteIndexAsync</code> / <code>DeleteAsync</code> 都返回「本次是否实际发生变化」，方便写幂等的初始化代码。</li><li>排序字段的可用性由后端决定，见 <a href="./search-engines-elasticsearch#与契约的已知差异">Elasticsearch 实现</a>。</li></ul><h2 id="相关模块" tabindex="-1">相关模块 <a class="header-anchor" href="#相关模块" aria-label="Permalink to &quot;相关模块&quot;">​</a></h2><ul><li><a href="./search-engines">XiHan.Framework.SearchEngines</a> — 进程内实现（默认兜底）。</li><li><a href="./search-engines-elasticsearch">XiHan.Framework.SearchEngines.Elasticsearch</a> — Elasticsearch 实现。</li></ul>',30)])])}const b=t(c,[["render",r]]);export{u as __pageData,b as default};
